function fmAssign(id){const o=S.songs[ui.es],f=o.fm,i=ui.fslot;if(lockedSong(o.id))return toast('Production is already confirmed.','err');if(i==null)return toast('Select a formation position first.','err');const m=get(id);if(o.tm&&m.team!=o.tm)return toast(`${m.name} is in ${m.team}; this song is exclusive to ${o.tm}.`,'err');const d=f.sl.find(x=>x.m==id);if(d)return toast(`${m.name} is already at position #${d.n}. Remove them first.`,'err');const x=f.sl[i],go=()=>{x.m=id;fmSync(o);const nx=slotOrder(f).find(k=>!f.sl[k].m);ui.fslot=nx==null?i:nx;toast(`${m.name} → #${x.n} (${rowNm(x.r,nRows(f.sl))}${x.c?', CENTER':''}).`);render()};if(x.m)ask(`Replace ${get(x.m).name} with ${m.name} at position #${x.n}?`,go,'Replace');else go()}
