function memAct(mid,v){if(!v)return;const m=get(mid),[k,a]=v.split(':');if(k=='prof'){ui.ptab='stats';ui.mod={t:'prof',id:mid};render()}else if(k=='cap'||k=='vice')setLead(m.group,k,m.tid,String(mid));else if(k=='st'||k=='rm')setStatus(mid,'trainee');else if(k=='mv')moveTeam(mid,a);else if(k=='tr'){const g=grp(+a);ask(`Transfer ${m.name} to ${g.name}? They leave their current team${isAct(m)?` and become a ${TL()} until you add them to one of ${g.name}'s teams`:''}. Generation and song history are kept.`,()=>transferGroup(mid,+a),'Transfer')}}
function mcardT(m,g){const t=teamOf(m),act=isAct(m)&&t;return`<div class="c m" style="padding:6px;border:3px solid ${bgOf(m)||'#fff'}">${ptc(m,64)}<div><b>${esc(m.name)}</b>${roleTag(m)}</div><div class="st">${ord(m.gen||1)} Gen${t?' · '+esc(t.name):''}</div><div class="st">${t?`Joined team: ${m.tjoined==null?'Unrecorded':jd(m.tjoined)}`:m.stSince!=null?`${esc(TL())} since ${jd(m.stSince)}`:''}</div><span class="tag" style="${act?'':'background:#ffe3a8'}">${act?'Active':esc(TL())}</span><select class="act" onchange="memAct(${m.id},this.value);this.value=''"><option value="">Actions…</option><option value="prof">Open profile</option>${act?'<option value="cap">Make Team Captain</option><option value="vice">Make Vice-Captain</option>':''}${act?`<option value="st">Demote to ${esc(TL())} (leaves team)</option>`:''}${g.teams.filter(x=>x.id!=m.tid).map(x=>`<option value="mv:${x.id}">${t?'Move to':'Add to'} ${esc(x.name)}${t?'':' (becomes active)'}</option>`).join('')}${S.groups.filter(x=>x.id!=g.id).map(x=>`<option value="tr:${x.id}">Transfer to group: ${esc(x.name)}</option>`).join('')}</select></div>`}
function addmHtml(M){const g=grp(M.gid),t=g.teams.find(x=>x.id==M.tid);if(!t)return'';M.sel=M.sel||[];const L=S.members.filter(m=>m.group==g.id&&m.tid!=t.id);return`<h2 class="ht">Add to ${esc(t.name)}</h2><p class="st">Tap members to select several, then confirm. Nobody moves until you press <b>Add selected</b>. ${esc(TL())}s who join become active members. A member belongs to one team, so joining moves them from their current team.</p><div class="row"><b>Selected: <span id="amcnt">${M.sel.length}</span></b><button class="b p" onclick="addConfirm()">Add selected</button><button class="b" onclick="ui.mod=null;render()">Cancel</button></div><div class="g" style="max-height:48vh;overflow:auto">${L.map(m=>`<div class="c m" id="am${m.id}" style="padding:4px;${cardSt(m)};${M.sel.includes(m.id)?'outline:3px solid var(--pk)':''}" onclick="togAdd(${m.id})">${ptc(m,50)}<div class="st"><b>${esc(m.name)}</b><br>${ord(m.gen||1)} Gen<br>${m.tid&&isAct(m)?esc(m.team)+' · Active':esc(TL())}</div></div>`).join('')||'<p class="st">Everyone in this group is already in the team.</p>'}</div>`}
function histHtml(m){const H=m.hist||[],gnm=h=>h.gname||gn(h.gid),cnt=c=>H.filter(h=>h.cat==c).length,row=h=>`<div class="hr"><div><b>${esc(h.title)}</b>${h.center?' <span class="tag rrUR">CENTER</span>':''}</div><div class="st">${jd(h.day)} · ${esc(gnm(h))}${h.rel&&h.rel!=h.title?' · '+esc(h.rel):''}${h.sname?' · '+esc(h.sname):''}${h.row!=null?` · Row ${h.row+1} #${h.pos}`:''}</div></div>`,sec=(c,t)=>{const L=H.filter(h=>h.cat==c).sort((a,b)=>b.day-a.day),n=L.filter(h=>h.center).length;return`<h3>${t} <span class="st">(${L.length}${n?` · Center ×${n}`:''})</span></h3>${L.map(row).join('')||'<p class="st">No songs yet.</p>'}`};
 return`<div class="row"><span class="pill">Main Songs ${cnt('main')}</span><span class="pill">Coupling Songs ${cnt('secondary')}</span><span class="pill">Center ×${H.filter(h=>h.center).length}</span></div>`+sec('main','Main Songs')+sec('secondary','Coupling Songs')}
function statusMigrate(){S.groups.forEach(g=>{if(g.active===undefined)g.active=true;if(g.debutDay===undefined)g.debutDay=null});if(S.producer===undefined)S.producer='';let ch=false;S.groups.forEach(g=>{(g.teams||[]).forEach(t=>{if(t.trainee){t.wasTrainee=true;delete t.trainee;ch=true}})});
 S.members.forEach(m=>{const t=teamOf(m);if(m.status=='trainee'&&m.tid){if(t)hev(m,{t:'team_leave',tid:t.id,tname:t.name,why:'reclass'});setTeamOf(m,null);ch=true}else if(m.status!='trainee'&&!m.tid){m.status='trainee';m.stSince=S.day;hev(m,{t:'reclass'});ch=true}});
 S.groups.forEach(g=>{g.teams=(g.teams||[]).filter(t=>{if(t.wasTrainee&&!S.members.some(m=>m.tid==t.id)){delete g.tl[t.id];return false}delete t.wasTrainee;return true})});if(ch)leadFix(false)}
function autoPanel(o,dis){const a=ui.aa=ui.aa||{attr:'pop',dir:'d',gen:'all',team:'all',rar:'all'},E=elig(o),op=(l,v)=>l.map(([k,n])=>`<option value="${k}" ${String(k)==String(v)?'selected':''}>${n}</option>`).join('');return`<div class="c" style="margin-top:8px"><h3>Auto Select</h3><div class="st">Fills all <b>${o.fm.size}</b> positions with <b>${o.fm.nc}</b> center${o.fm.nc>1?'s':''}, as set in Song settings. Members fill your current formation: the best-ranked take the centers and the highest-share positions.</div><div class="row"><label class="st">Rank by <select ${dis} onchange="ui.aa.attr=this.value;render()">${op(STATS.map(x=>[x[0],x[1]]),a.attr)}</select></label><select ${dis} onchange="ui.aa.dir=this.value;render()">${op([['d','Highest first'],['a','Lowest first']],a.dir)}</select></div><div class="row"><select ${dis} onchange="ui.aa.gen=this.value;render()">${op([['all','All Generations'],...gensOf(E).map(g=>[g,ord(g)+' Generation'])],a.gen)}</select>${o.tm?'':`<select ${dis} onchange="ui.aa.team=this.value;render()">${op(teamOpts(),a.team)}</select>`}<select ${dis} onchange="ui.aa.rar=this.value;render()">${op([['all','All rarities'],['UR','UR'],['SR','SR'],['R','R'],['N','N']],a.rar)}</select><button class="b p" ${dis} onclick="autoAdv()">Apply</button></div><p class="st">The best-ranked members take the center positions. You can still replace or move members by hand, then save.</p></div>`}
function autoAdv(){const o=S.songs[ui.es];if(lockedSong(o.id))return toast('Production is already confirmed.','err');const a=ui.aa,n=o.fm.size,nc=o.fm.nc;
 const pool=elig(o).filter(m=>(a.gen=='all'||(m.gen||1)==+a.gen)&&teamMatch(m,a.team)&&(a.rar=='all'||rar(m)==a.rar)).sort((x,y)=>((a.dir=='a'?-1:1)*(sv(y,a.attr)-sv(x,a.attr)))||x.id-y.id).slice(0,n).map(m=>m.id);if(!pool.length)return toast('No eligible members match those filters.','err');
 const go=()=>{applyIds(o,pool);ui.fslot=slotOrder(o.fm)[0];toast(pool.length<n?`Only ${pool.length} eligible member(s) matched, so ${n-pool.length} of ${n} position(s) are still empty. Loosen the filters, or fill them by hand.`:`All ${n} positions filled (${nc} center${nc>1?'s':''}) by ${(STATS.find(x=>x[0]==a.attr)||['',''])[1]}. Review, then save.`,pool.length<n?'err':'ok');render()};if(o.fm.sl.some(x=>x.m))ask('Auto selection will replace the entire current lineup of this song. The member count and number of centers stay the same.',go,'Replace lineup');else go()}
function profJoin(mid,tid){if(tid)moveTeam(mid,tid)}
CFG.posW={center:5,beside:4,front:3,mid:2,back:1,fall:.3};CFG.rep.pool=1.2;CFG.maxRows=5;CFG.trBg='#cfc8dc';
const SNAMES=['Senbatsu','Under Girls','Next Girls','Future Girls','Upcoming Girls','Theater Girls'];
const nRows=sl=>sl.length?Math.max(...sl.map(x=>x.r))+1:1,rowsOf=sl=>{const n=nRows(sl),c=Array(n).fill(0);sl.forEach(x=>c[x.r]++);return c},rowCounts=a=>rowsOf(a).join('-');
const defRows=(size,nc)=>rowsOf(defForm(size,nc)).filter(x=>x>0);
function buildForm(rows,nc){const F=rows[0],st=Math.max(0,(F-nc)>>1),sl=[];let n=0;rows.forEach((c,r)=>{for(let i=0;i<c;i++)sl.push({r,i,n:++n,c:r==0&&i>=st&&i<st+nc?1:0,m:null})});return sl}
const genForm=(size,nc)=>buildForm(defRows(size,nc),nc);
const rowSh=(r,n)=>n<=1||r==0?'Front':r==n-1?'Back':'Middle',rowNm=(r,n)=>`Row ${r+1} · ${rowSh(r,n)}`;
function posWeights(sl){const W=CFG.posW,R=rowsOf(sl),nR=R.length,f0=sl.filter(x=>x.r==0),cs=f0.filter(x=>x.c).map(x=>x.i),st=cs.length?Math.min(...cs):0,ce=cs.length?Math.max(...cs):-1,kOf=x=>x.i<st?st-1-x.i:x.i-ce-1,km=Math.max(1,...f0.filter(x=>!x.c&&x.i!=st-1&&x.i!=ce+1).map(kOf));
 return sl.map(x=>{if(x.c)return W.center;if(x.r==0){if(x.i==st-1||x.i==ce+1)return W.beside;const k=kOf(x),dn=km>1?(k-1)/(km-1):0;return W.front*(1-W.fall*dn)}const base=nR==2?W.back:W.mid-(W.mid-W.back)*(x.r-1)/(nR-2),hw=(R[x.r]-1)/2,dn=hw>0?Math.abs(x.i-hw)/hw:0;return base*(1-W.fall*dn)})}
function posShares(sl){const w=posWeights(sl),idx=sl.map((x,k)=>k).filter(k=>sl[k].m),tot=idx.reduce((a,k)=>a+w[k],0),sh=new Map();if(!tot)return{sh,pct:new Map()};idx.forEach(k=>sh.set(k,w[k]/tot));
 const raw=idx.map(k=>({k,v:sh.get(k)*1000})),fl=raw.map(x=>({k:x.k,f:Math.floor(x.v),r:x.v-Math.floor(x.v)}));let left=1000-fl.reduce((a,x)=>a+x.f,0);[...fl].sort((a,b)=>b.r-a.r||a.k-b.k).forEach(x=>{if(left>0){x.f++;left--}});return{sh,pct:new Map(fl.map(x=>[x.k,x.f/10]))}}
function slotOrder(f){const w=posWeights(f.sl),R=rowsOf(f.sl),d=k=>Math.abs(f.sl[k].i-(R[f.sl[k].r]-1)/2);return f.sl.map((_,k)=>k).sort((a,b)=>(w[b]-w[a])||(f.sl[a].r-f.sl[b].r)||(d(a)-d(b))||a-b)}
function planReshape(f,rows,nc){const old=f.sl,o0=old.filter(x=>x.r==0).sort((a,b)=>a.i-b.i),C=o0.filter(x=>x.c).map(x=>x.m),cs=o0.filter(x=>x.c).map(x=>x.i),st0=cs.length?Math.min(...cs):0,ce0=cs.length?Math.max(...cs):-1;
 let L=o0.filter(x=>!x.c&&x.i<st0).sort((a,b)=>b.i-a.i).map(x=>x.m),Rt=o0.filter(x=>!x.c&&x.i>ce0).sort((a,b)=>a.i-b.i).map(x=>x.m),cen=C.slice();
 if(nc>cen.length){let side=0;while(cen.length<nc){if(side%2==0&&Rt.length)cen.push(Rt.shift());else if(L.length)cen.push(L.shift());else if(Rt.length)cen.push(Rt.shift());else cen.push(null);side++}}
 else while(cen.length>nc){Rt.unshift(cen.pop());if(cen.length>nc)L.unshift(cen.shift())}
 const sl=buildForm(rows,nc),F=rows[0],st=(F-nc)>>1,lc=st,rc=F-st-nc,at=(r,i)=>sl.find(x=>x.r==r&&x.i==i),dis=[];
 cen.forEach((m,j)=>{at(0,st+j).m=m});L.forEach((m,j)=>{if(j<lc)at(0,st-1-j).m=m;else if(m)dis.push(m)});Rt.forEach((m,j)=>{if(j<rc)at(0,st+nc+j).m=m;else if(m)dis.push(m)});
 old.filter(x=>x.r>0).sort((a,b)=>a.r-b.r||a.i-b.i).forEach(x=>{const t=x.r<rows.length&&x.i<rows[x.r]?at(x.r,x.i):null;if(t)t.m=x.m;else if(x.m)dis.push(x.m)});
 const fo={sl};slotOrder(fo).filter(k=>!sl[k].c&&!sl[k].m).forEach(k=>{if(dis.length)sl[k].m=dis.shift()});return{sl,dropped:dis}}
function applyReshape(o,rows,nc,msg){if(lockedSong(o.id))return toast('Production is already confirmed.','err');const P=planReshape(o.fm,rows,nc),go=()=>{o.fm.sl=P.sl;o.fm.size=P.sl.length;o.fm.nc=nc;fmSync(o);ui.fslot=null;ui.sw=null;toast(msg);render()};
 if(P.dropped.length)ask(`${msg}\nThere is no room left for: ${P.dropped.map(i=>get(i)?.name).join(', ')}. They will return to the member list.`,go,'Apply');else go()}
const cur=()=>S.songs[ui.es],isDef=f=>rowsOf(f.sl).join()==defRows(f.size,f.nc).join();
function rowAdj(r,d){const o=cur(),f=o.fm,R=rowsOf(f.sl),n=R[r]+d,tot=f.size+d,ms=maxSize(o);if(n<1)return toast('A row needs at least 1 position. Use "Remove row" to delete it.','err');if(r==0&&n<f.nc)return toast(`Row 1 must keep room for the ${f.nc} center${f.nc>1?'s':''}. Lower the number of centers first.`,'err');if(tot>ms)return toast(`The lineup can have at most ${ms} members.`,'err');R[r]=n;applyReshape(o,R,f.nc,`Row ${r+1} now has ${n} position${n>1?'s':''} (lineup ${tot} members).`)}
function addRow(){const o=cur(),f=o.fm,R=rowsOf(f.sl);if(R.length>=CFG.maxRows)return toast(`A formation can have at most ${CFG.maxRows} rows.`,'err');if(f.size>=maxSize(o))return toast(`The lineup already has the maximum ${maxSize(o)} members. Remove a position elsewhere first.`,'err');R.push(1);applyReshape(o,R,f.nc,`Row ${R.length} added at the back.`)}
function rmRow(r){const o=cur(),f=o.fm,R=rowsOf(f.sl);if(R.length<=1)return toast('A formation needs at least 1 row.','err');if(r==0)return toast('Row 1 holds the centers and cannot be removed.','err');R.splice(r,1);applyReshape(o,R,f.nc,`Row ${r+1} removed (lineup ${R.reduce((a,b)=>a+b,0)} members).`)}
function resetForm(){const o=cur(),f=o.fm;applyReshape(o,defRows(f.size,f.nc),f.nc,'Default formation restored for this lineup size.')}
function setSize(n){const o=cur(),f=o.fm,ms=maxSize(o);n=+n;if(lockedSong(o.id))return toast('Production is already confirmed.','err');if(n<1||n>ms){toast(`Size must be 1–${ms}${o.tm?` (${o.tm} has ${ms} eligible members)`:''}.`,'err');return render()}if(n==f.size)return;if(f.nc>n){toast(`You have ${f.nc} centers, which is more than ${n} members. Lower the number of centers first.`,'err');return render()}
 let R;if(isDef(f))R=defRows(n,f.nc);else{R=rowsOf(f.sl);while(R.reduce((a,b)=>a+b,0)<n){let t=R.length>1?1:0;for(let r=1;r<R.length;r++)if(R[r]<=R[t])t=r;R[t]++}while(R.reduce((a,b)=>a+b,0)>n){let t=-1;for(let r=0;r<R.length;r++){if(r==0?R[0]>f.nc:R[r]>1){if(t<0||R[r]>=R[t])t=r}}if(t<0){R.pop();continue}R[t]--}}
 applyReshape(o,R,f.nc,`Lineup set to ${n} members${isDef(f)?'':' (your custom rows were kept and adjusted)'}.`)}
function setNc(n){const o=cur(),f=o.fm;n=+n;if(lockedSong(o.id))return toast('Production is already confirmed.','err');if(n<1||n>Math.min(CFG.maxCenters,f.size,elig(o).length)){toast('Invalid number of centers for this size.','err');return render()}if(n==f.nc)return;
 let R=isDef(f)?defRows(f.size,n):rowsOf(f.sl);if(!isDef(f))while(R[0]<n){let t=R.length-1;while(t>0&&R[t]==0)t--;if(t==0)break;R[t]--;if(!R[t])R.splice(t,1);R[0]++}applyReshape(o,R,n,`${n} center${n>1?'s':''} now stand${n>1?'':'s'} in the middle of Row 1.`)}
const repPool=(o,b)=>b*(o.role=='Main'?CFG.rep.main:CFG.rep.coup)*o.fm.sl.filter(x=>x.m).length*CFG.rep.pool;
const fmEst=o=>{const P=posShares(o.fm.sl),pool=repPool(o,CFG.rep.base),nR=nRows(o.fm.sl);return o.fm.sl.map((x,k)=>[x,k]).filter(([x])=>x.m&&get(x.m)).map(([x,k])=>({x,k,m:get(x.m),share:P.sh.get(k),pct:P.pct.get(k),g:pool*P.sh.get(k),row:rowNm(x.r,nR)}))};
function grantRep(o,base){o.rep=o.rep||{};if(o.rep.rel||!o.fm)return[];o.rep.rel=1;const P=posShares(o.fm.sl),pool=repPool(o,base),nR=nRows(o.fm.sl);return o.fm.sl.map((x,k)=>[x,k]).filter(([x])=>x.m&&get(x.m)).map(([x,k])=>{const m=get(x.m),d=Math.max(1,Math.round(pool*P.sh.get(k)));gainPop(m,d);m.mor=cl(m.mor+4);return{mid:m.id,n:m.name,song:o.title,sname:o.sname||'Senbatsu',role:o.role=='Main'?'Main':'Coupling',row:rowNm(x.r,nR),pos:x.n,pct:P.pct.get(k),c:x.c,gain:d}})}
function setSname(id,v){const o=S.songs[id];if(lockedSong(id))return toast('Production is already confirmed.','err');v=String(v||'').replace(/[<>"'`\\]/g,'').replace(/\s+/g,' ').trim().slice(0,30);if(!v){toast('The senbatsu name cannot be empty.','err');return render()}o.sname=v;toast(`Lineup of "${o.title}" is now called "${v}".`);render()}
const snameIn=(o,dis)=>`<label class="st">Senbatsu name <input list="snl" value="${esc(o.sname||'Senbatsu')}" maxlength="30" ${dis} style="width:150px" onchange="setSname('${o.id}',this.value)"></label><datalist id="snl">${SNAMES.map(x=>`<option value="${x}">`).join('')}</datalist>`;
const teamLbl=m=>{const t=teamOf(m);return t&&isAct(m)?t.name:TL()},cardSt=m=>{const c=bgOf(m)||CFG.trBg;return`background:${tint(c,.8)};border:2px solid ${tint(c,.35)}`};
function perfPos(m){const out=[];if(S.pj)usedSongs(S.pj).forEach(i=>{const o=S.songs[i],x=o.fm.sl.find(y=>y.m==m.id);if(x)out.push({cur:1,title:o.title,sname:o.sname||'Senbatsu',row:x.r,rows:nRows(o.fm.sl),pos:x.n,c:x.c,main:i==S.pj.mainId})});
 const H=(m.hist||[]).filter(h=>h.cat=='main').sort((a,b)=>b.day-a.day)[0];if(H)out.push({title:H.title,sname:H.sname,row:H.row,rows:H.rows,pos:H.pos,c:H.center,main:1,day:H.day});return out}
