function rsCenter(){try{const rm=document.querySelector('.rsmap'),sv=rm&&rm.querySelector('svg');if(!rm||!sv||rm.scrollWidth<=rm.clientWidth+2)return;const P=ui.rsp||{},l=RSL[P.loc],W=Math.max(...Object.values(RSL).filter(z=>z.kind==(P.tab||'jp')).map(z=>z.x))+1,cx=l&&l.kind==(P.tab||'jp')?l.x+.5:(P.tab=='as'?7.5:8.5);rm.scrollLeft=Math.max(0,cx/W*rm.scrollWidth-rm.clientWidth/2)}catch(e){}}
