function rsErrs(P,x,l){const e=[];if(!x)return['Choose a released single to promote.'];if(!l)return['Choose a destination on the map.'];if(rsUsed(x.rid,l.id))e.push(`${l.n} already hosted (or is booked for) a Roadshow for this single.`);const ids=rsPlanIds(P,x);if(!ids.length)e.push(P.mode=='full'?'This single\'s group has no active team members.':'Select at least one member.');
 if(P.day==null)e.push('Pick the event date on the calendar.');else if(P.day<S.day+7)e.push('Roadshows must be booked at least 7 days ahead.');else ids.forEach(id=>{const b=busy(id,[P.day,P.day+1]);if(b.length)e.push(`${get(id).name} is busy then: ${b[0].title}.`)});
 const s1=P.smode=='same'?P.sl1:P.sl1,s2=P.smode=='same'?P.sl1:P.sl2;e.push(...rsSlErr(s1,x,1));if(P.smode!='same')e.push(...rsSlErr(s2,x,2));if(P.day!=null&&ids.length){const c=rsCostL(l,ids,P.day,x);if(c.L.reduce((a,y)=>a+y[1],0)>S.money)e.push(`Not enough money for the expenses (${yen(c.L.reduce((a,y)=>a+y[1],0))}).`)}return e}
