function rsBook(){if(!ui.rsp||!ui.rsp.plan)return toast('Open the planner for a location first.','err');const P=ui.rsp,x=S.singles.find(s=>s.rid==P.rid),l=RSL[P.loc],e=rsErrs(P,x,l);if(e.length)return toast(e[0],'err');const ids=rsPlanIds(P,x),c=rsCostL(l,ids,P.day,x),tot=c.L.reduce((a,y)=>a+y[1],0),sl1=JSON.parse(JSON.stringify(P.sl1)),sl2=P.smode=='same'?null:JSON.parse(JSON.stringify(P.sl2));
 ask(`Book a Roadshow in ${l.n} (${l.venue}) on ${wd(P.day)} & ${wd(P.day+1)} with ${ids.length} member(s)? Expenses ${yen(tot)} are paid now.`,()=>{if(rsUsed(x.rid,l.id))return toast('Already booked.','err');if(!spend(tot,`Roadshow booking: ${l.n} (${x.title})`))return;S.cal.push({id:'rs'+(++S.sid),type:'road',v:2,rid:x.rid,st:x.title,loc:l.id,kind:l.kind,title:`Roadshow — ${l.n} (${x.title})`,venue:l.venue,vt:l.vt,day:P.day,dur:2,members:ids,mode:P.mode,smode:P.smode,sl1,sl2,est:c.L,cost:tot,booked:S.day,done:false,d1:null,d2:null});ui.rsp={rid:P.rid,loc:P.loc,tab:P.tab,plan:false};toast(`Roadshow in ${l.n} booked for ${wd(P.day)}.`);render()},'Book Roadshow')}
function rsCal(P){const o=P.cm|0,b=dt(),first=new Date(b.getFullYear(),b.getMonth()+o,1),y=first.getFullYear(),mo=first.getMonth(),n=new Date(y,mo+1,0).getDate(),idx=dd=>Math.round((new Date(y,mo,dd)-new Date(2026,3,1))/86400000);let c='';for(let i=0;i<first.getDay();i++)c+='<div></div>';
 for(let dd=1;dd<=n;dd++){const k=idx(dd),ok=k>=S.day+7,ev=(S.cal||[]).filter(e=>evDays(e).includes(k)),selD=P.day!=null&&(k==P.day||k==P.day+1);c+=`<button class="b s" style="padding:4px 0;min-width:0;${selD?'background:var(--pk);color:#fff':ok?'':'opacity:.35'}" ${ok?`onclick="ui.rsp.day=${k};render()"`:'disabled'} title="${esc(ev.map(e=>e.title).join('; '))}">${dd}${ev.length?'•':''}${[0,6].includes(new Date(y,mo,dd).getDay())?'':''}</button>`}
 return`<div class="row"><button class="b s" onclick="ui.rsp.cm=(ui.rsp.cm|0)-1;render()">◀</button><b>${first.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</b><button class="b s" onclick="ui.rsp.cm=(ui.rsp.cm|0)+1;render()">▶</button></div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:3px">${['S','M','T','W','T','F','S'].map(x=>`<b class="st" style="text-align:center">${x}</b>`).join('')}${c}</div><div class="st">Days earlier than ${wd(S.day+7)} can't be booked (7 days' notice). • = something already scheduled.</div>`}
